theorem actual_clock_backtracking_positive :
    0 < gaussianProduct {ω | |IBMConstructedSources.clockPath ω 2| <
      |IBMConstructedSources.clockPath ω 1|}

theorem slope_positive_bulk {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : Continuous ρ)
    (hmass : (∫ u, ρ u) = 1) {B x : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ B) (hx : B < x) : deriv (wholeLineVariance ρ) x = 1

theorem slope_negative_bulk {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : Continuous ρ)
    (hmass : (∫ u, ρ u) = 1) {B x : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ B) (hx : x < -B) : deriv (wholeLineVariance ρ) x = -1

theorem dilate_support {ρ : ℝ → ℝ} {R ε : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ R) (hε : 0 < ε) {z : ℝ}
    (hz : dilate ρ ε z ≠ 0) : |z| ≤ ε * R

theorem shifted_support {ρ : ℝ → ℝ} {R ε : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ R) (hε : 0 < ε) (x r : ℝ)
    (hr : r ∉ Set.Icc (x - ε * R) (x + ε * R)) : dilate ρ ε (x-r) = 0

theorem spatial_hasDerivAt (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 1 ρ) (r : ℝ) :
    HasDerivAt (spatial g a ρ) (slope g a ρ r) r

theorem slope_hasDerivAt (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) (r : ℝ) :
    HasDerivAt (slope g a ρ) (curvature g a ρ r) r

theorem slope_bound (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ r, ‖slope g a ρ r‖ ≤ C

theorem curvature_bound (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ r, ‖curvature g a ρ r‖ ≤ C

def derivativeLip {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ)
    (hρ : ContDiff ℝ 2 ρ) (hmass : (∫ x, ρ x) = 1) :
    LipschitzWith (curvatureBound hc hρ.continuous hmass) (deriv (wholeLineVariance ρ))

def errorClass {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ)
    (hpos : ∀ z, 0 ≤ ρ z) (hmass : (∫ z, ρ z) = 1) (heven : ∀ z, ρ (-z) = ρ z)
    (T : ℝ≥0) : GaussianL2

def weightedClass {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ)
    (hpos : ∀ z, 0 ≤ ρ z) (hmass : (∫ z, ρ z) = 1) (heven : ∀ z, ρ (-z) = ρ z)
    (T : ℝ≥0) : GaussianL2

theorem residual_tendsto_nonzero {ι : Type*} {l : Filter ι} {ε : ι → ℝ}
    (hε : ∀ i, 0 < ε i) (hlim : Tendsto ε l (𝓝 0)) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : Continuous ρ) (hmass : (∫ z, ρ z) = 1)
    {M : ℝ} (hM : ∀ x, ‖φ x‖ ≤ M) (r : ℝ) (hr : r ≠ 0) :
    Tendsto (fun i => residual hφ (dilate ρ (ε i)) r) l (𝓝 0)

theorem pathIntegral_bound {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : Continuous ρ)
    (hpos : ∀ z, 0 ≤ ρ z) (hmass : (∫ z, ρ z) = 1) {M : ℝ}
    (hM : ∀ x, ‖φ x‖ ≤ M) (T : ℝ≥0) (ω : SampleSpace) : ‖pathIntegral hφ ρ T ω‖ ≤ (M/4)*T

theorem pathIntegral_memLp {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ)
    (hpos : ∀ z, 0 ≤ ρ z) (hmass : (∫ z, ρ z) = 1) {M : ℝ}
    (hM : ∀ x, ‖φ x‖ ≤ M) (T : ℝ≥0) : MemLp (pathIntegral hφ ρ T) 2 gaussianProduct

def integralClass {ρ : ℝ → ℝ} (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ)
    (hpos : ∀ z, 0 ≤ ρ z) (hmass : (∫ z, ρ z) = 1) {M : ℝ}
    (hM : ∀ x, ‖φ x‖ ≤ M) (T : ℝ≥0) : GaussianL2

def originalClass (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) (hpos : ∀ x, 0 ≤ ρ x)
    (hmass : (∫ x, ρ x) = 1) (heven : ∀ x, ρ (-x) = ρ x) (T : ℝ≥0) : GaussianL2
